// --- FUNCTION NODE: AGREGASI 30 MENIT 
// Fitur:
// 1. AVG 
// 2. Timestamp End-of-Period
// 3. Support Offline Cache hingga 7 HARI 
// 4. Realtime Update

msg.topic = `
INSERT INTO sensor_history (plc_code, sensor_code, value, timestamp)
SELECT
    plc_code,
    sensor_code,

    -- RATA-RATA SAJA
    AVG(value) AS value,

    -- LOGIKA TIMESTAMP (PEMBULATAN 30 MENIT)
    FROM_UNIXTIME(
        CEILING(UNIX_TIMESTAMP(timestamp) / 1800) * 1800
    ) AS time_bucket

FROM sensor_realtime

WHERE
    -- Kita ambil data mundur sampai 7 HARI (1 Pekan) ke belakang.
    -- Jadi kalau data dari 3 hari lalu baru masuk sekarang, dia tetap akan diproses.
    timestamp >= DATE_SUB(NOW(), INTERVAL 7 DAY)

GROUP BY plc_code, sensor_code, time_bucket

-- LIVE UPDATE
ON DUPLICATE KEY UPDATE
    value = VALUES(value);
`;

return msg;

// ======================================================
// PARSE MQTT TOPIC
// ======================================================
if (typeof msg.topic !== "string") return null;

let parts = msg.topic.split("/");
let plc_code = parts[3];

let payload = msg.payload || {};
let sensor_code = (payload._groupName || "").toString().trim();
let timestamp = payload._terminalTime;
let rawValue = payload.data;
let cycleValue = payload.data_cycle;   // undefined jika bukan cycle sensor

if (!plc_code || !sensor_code || !timestamp) return null;


// ======================================================
// GLOBAL STATE (status online / lastSeen)
// ======================================================
let lastSeenSensor = flow.get("lastSeenSensor") || {};
let statusSensor = flow.get("statusSensor") || {};

let sensorKey = `${plc_code}/${sensor_code}`;
let now = Date.now();

// Update last seen
lastSeenSensor[sensorKey] = now;
flow.set("lastSeenSensor", lastSeenSensor);


// ======================================================
// ONLINE FIRST LOG
// ======================================================
if (statusSensor[sensorKey] !== "online") {
    statusSensor[sensorKey] = "online";
    flow.set("statusSensor", statusSensor);

    return {
        topic: `
            INSERT INTO sensor_log 
            (plc_code, sensor_code, status, event_time)
            VALUES ('${plc_code}', '${sensor_code}', '1', '${timestamp}');
        `
    };
}


// ======================================================
// VALUE CONVERSION
// ======================================================
let measurement_code = sensor_code.substring(2, 4);
let valueConverted;

switch (measurement_code) {
    case "01": valueConverted = parseFloat(rawValue) / 1000; break;
    case "02":
    case "03":
    case "04": valueConverted = parseFloat(rawValue) / 10; break;
    default: valueConverted = parseFloat(rawValue);
}


// ======================================================
// SENSOR TYPE CHECK (cycle atau tidak)
// ======================================================
let isCycleSensor = (cycleValue !== undefined && cycleValue !== null);


// ======================================================
// BUILD SQL FOR 1 TABLE
// ======================================================
let finalCycle = isCycleSensor ? parseInt(cycleValue, 10) || 0 : null;

msg.topic = `
    INSERT INTO sensor_realtime
    (plc_code, sensor_code, value, data_cycle, timestamp)
    VALUES (
        '${plc_code}', 
        '${sensor_code}', 
        ${valueConverted}, 
        ${finalCycle === null ? 'NULL' : finalCycle}, 
        '${timestamp}'
    );
`;

return msg;

let lastSeenSensor = flow.get("lastSeenSensor") || {};
let statusSensor = flow.get("statusSensor") || {};

let timeoutMs = 65000; // interval PLC = 1 menit → timeout 65 detik
let now = Date.now();

let queries = [];

for (let key in lastSeenSensor) {
    let last = lastSeenSensor[key];

    if (now - last > timeoutMs) {

        if (statusSensor[key] !== "offline") {
            statusSensor[key] = "offline";
            flow.set("statusSensor", statusSensor);

            let [plc_code, sensor_code] = key.split("/");

            queries.push(`
                INSERT INTO sensor_log 
                (plc_code, sensor_code, status, event_time)
                VALUES ('${plc_code}', '${sensor_code}', '0', NOW());
            `);
        }
    }
}

if (queries.length > 0) {
    return { topic: queries.join("\n") };
}

return null;

// Contoh: msg.topic = "data/07/RT0201/7020449001020126076"
// Ambil sensor code dari topik MQTT
const topicParts = msg.topic.split("/");
const sensorCode = topicParts[2]; // "RT0201"

// Ambil data dari payload
const data = msg.payload;

// Pastikan payload valid
if (!data || !sensorCode) return null;

// Buat pesan bersih untuk WebSocket
msg.payload = {
  sensor_code: sensorCode,
  value: Number(data.value),
  timestamp: data._terminalTime
};

return msg;

// function node — output ke MySQL (pastikan function node memiliki 3 output seperti sebelumnya)
if (typeof msg.payload === "string") {
    try { msg.payload = JSON.parse(msg.payload); } 
    catch (e) {
        node.error("Invalid JSON", msg);
        msg.statusCode = 400; msg.payload = { error: "Invalid JSON" };
        return [null, msg, null];
    }
}

const data = msg.payload;
if (!data.sensor_code || data.value === undefined) {
    msg.statusCode = 400; msg.payload = { error: "sensor_code dan value wajib diisi" };
    return [null, msg, null];
}

// Ambil timestamp; jika tidak ada gunakan now
let ts = data.timestamp || new Date().toISOString();
// ubah ISO -> "YYYY-MM-DD HH:MM:SS"
ts = ts.replace('T', ' ').replace('Z', '').split('.')[0]; // menghapus ms

// buat query (nilai numeric tanpa quotes)
msg.topic = `
  INSERT INTO sensor_history (sensor_code, value)
  VALUES ('${data.sensor_code}', ${Number(data.value)})
`;

node.warn("Query: " + msg.topic);
return [msg, null, msg];

msg.payload = { success: true, message: "Data berhasil disimpan" };
msg.statusCode = 200;
return msg;

let rows = msg.payload;

// Pastikan hasil dari MySQL berupa array
if (!Array.isArray(rows)) {
    node.warn("Payload bukan array, isi payload: " + JSON.stringify(rows));
    msg.payload = {
        status: "error",
        message: "Data dari database tidak berupa array",
        raw_payload: rows
    };
    return msg;
}

// Format response API
msg.payload = {
    status: "success",
    timestamp_api: new Date().toLocaleString("id-ID", { timeZone: "Asia/Jakarta" }),
    sensors: rows.map(r => {
        let timestamp = new Date(r.timestamp);
        return {
            plc_code: r.plc_code, // kalau kolom ini ada di tabel
            sensor_code: r.sensor_code,
            value: r.value,
            timestamp: timestamp.toLocaleString("id-ID", { timeZone: "Asia/Jakarta" })
        };
    })
};

return msg;

// Ambil sensor dari URL parameter
const sensorCode = msg.req.params.sensor;

let sql = `
SELECT sr.plc_code, sr.sensor_code, sr.value, sr.timestamp
FROM sensor_realtime sr
INNER JOIN (
    SELECT sensor_code, MAX(timestamp) AS latest_timestamp
    FROM sensor_realtime
    GROUP BY sensor_code
) t
ON sr.sensor_code = t.sensor_code
AND sr.timestamp = t.latest_timestamp
`;

if (sensorCode) {
    sql += ` WHERE sr.sensor_code = '${sensorCode}'`;
}

sql += " ORDER BY sr.sensor_code;";

msg.topic = sql;
return msg;
